ALTER TABLE operation_task ADD COLUMN required_role_key TEXT, ADD COLUMN scheduled_start TIMESTAMPTZ(6), ADD COLUMN scheduled_end TIMESTAMPTZ(6), ADD COLUMN series_key TEXT, ADD COLUMN series_config_rule_id UUID;
ALTER TABLE operation_task ADD CONSTRAINT operation_task_schedule_order CHECK ((scheduled_start IS NULL AND scheduled_end IS NULL) OR (scheduled_start IS NOT NULL AND scheduled_end IS NOT NULL AND scheduled_end > scheduled_start));
CREATE INDEX operation_task_person_schedule_idx ON operation_task(organization_id, assigned_to_person_id, scheduled_start, scheduled_end);
CREATE INDEX operation_task_series_date_idx ON operation_task(organization_id, series_key, due_date);

INSERT INTO config_rule(organization_id,key,scope_type,value,effective_from,version,reason) SELECT o.id,'ops.task_policy','organization','{"shift_start_minute": 540, "risk_window_minutes": 120, "recurrence_horizon_days": 14, "recurrence_lookback_days": 7, "evidence_max_bytes": 3000000, "evidence_link_seconds": 120, "readiness_types": ["ARRIVAL_PREPARATION", "CHECKOUT_CLEANING", "CLEANING", "INSPECTION"], "types": {"ARRIVAL_PREPARATION": {"role_keys": ["housekeeper", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60, "start_minute": 900}, "CHECKOUT_CLEANING": {"role_keys": ["housekeeper", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60, "start_minute": 720}, "CLEANING_MIDSTAY": {"role_keys": ["housekeeper", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "CLEANING": {"role_keys": ["housekeeper", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "INSPECTION": {"role_keys": ["qa_inspector", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "POOL": {"role_keys": ["pool_technician", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "GARDEN": {"role_keys": ["gardener", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "MAINTENANCE": {"role_keys": ["maintenance", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "LAUNDRY": {"role_keys": ["housekeeper", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "INVENTORY": {"role_keys": ["field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "CHEF": {"role_keys": ["chef", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "TRANSFER": {"role_keys": ["driver", "field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}, "CUSTOM": {"role_keys": ["field_staff", "admin"], "preferred_people": [], "fallback_people": [], "max_daily_tasks": 8, "duration_minutes": 60}}}'::jsonb,'1970-01-01'::timestamptz,1,'Initial editable Operations policy' FROM organization o WHERE NOT EXISTS(SELECT 1 FROM config_rule c WHERE c.organization_id=o.id AND c.key='ops.task_policy' AND c.scope_type='organization');
